pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }

    function testFuzz_property(address actor, uint96 a0, uint96 a1, uint8 len) public {
        vm.assume(actor != address(0));
        uint256 l = uint256(bound(len, 1, 2));

        Reverter rev = new Reverter();

        address[] memory tos = new address[](l);
        uint[] memory vs = new uint[](l);
        for (uint i = 0; i < l; i++) {
            tos[i] = address(0xABCD);
            vs[i] = (i == 0) ? uint(a0) : uint(a1);
        }

        bool ok;
        vm.prank(actor);
        try c.transfer(address(rev), tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert from callee");
    }
}
